(()=>{const f=facilities.find(x=>x.id==='moe_1010004');if(!f)return;const source='https://www.city.takasaki.gunma.jp/page/2445.html';const note='高崎市公式の吉井クリーンセンター施設概要で、1991年3月着工、1992年9月竣工、15t/8h×2炉（30t/日）、機械化バッチ式を確認。2003年3月のダイオキシン類対策工事とは分離。当初設計施工者の氏名は公式概要に記載なし。';f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');if(!f.builder)f.builder_research_status='当初施工会社未確認（自治体公式で竣工・炉形式の世代照合済み）';})();